const timelineItems=document.querySelectorAll(".timeline__item"),timelinePanel=document.querySelector("#timeline-panel"),timelineImage=document.querySelector("#timeline-image"),timelineYear=document.querySelector("#timeline-year"),timelineTitle=document.querySelector("#timeline-title"),timelineCompany=document.querySelector("#timeline-company"),timelineDescription=document.querySelector("#timeline-description"),timelineTechnologies=document.querySelector("#timeline-technologies");function updateTimeline(e){timelineItems.forEach(t=>{const i=t===e;t.classList.toggle("is-active",i),t.setAttribute("aria-selected",String(i)),t.tabIndex=i?0:-1}),timelinePanel.setAttribute("aria-labelledby",e.id),timelineYear.textContent=e.dataset.year,timelineTitle.textContent=e.dataset.title,timelineCompany.textContent=e.dataset.company,timelineDescription.textContent=e.dataset.description,timelineTechnologies.textContent=e.dataset.technologies,timelineImage.src=e.dataset.image,timelineImage.alt=e.dataset.alt}timelineItems.forEach((e,t)=>{e.addEventListener("click",()=>{updateTimeline(e)}),e.addEventListener("keydown",e=>{if(!["ArrowLeft","ArrowRight","ArrowUp","ArrowDown","Home","End"].includes(e.key))return;let i;if(e.preventDefault(),"Home"===e.key)i=0;else if("End"===e.key)i=timelineItems.length-1;else{i="ArrowLeft"===e.key||"ArrowUp"===e.key?(t-1+timelineItems.length)%timelineItems.length:(t+1)%timelineItems.length}timelineItems[i].focus(),updateTimeline(timelineItems[i])})});